const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function toast(m){let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.textContent=m;t.className='show';clearTimeout(toast.h);toast.h=setTimeout(()=>t.className='',2600)}
const COL={NORMAL:'--normal',CAUTION:'--caution',HIGH:'--high',AVOID:'--avoid',MORNING:'--accent',SYSTEM:'--accent'};
const css=n=>getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const colr=l=>css(COL[l]||'--mute');
const SIG={gps_jamming_cluster:'GPS degradation cluster',military_spike:'Military aircraft spike',tanker_dark_gap:'Tanker AIS anomaly',conflict_news_spike:'Conflict news velocity',crude_confirmation:'Crude confirmation',vix_confirmation:'India VIX confirmation'};
const RN={hormuz:'Strait of Hormuz',red_sea:'Red Sea / Gulf of Aden',india_pak:'India-Pakistan border',all:'All regions',global:'Global',system:'System'};
const PLAY={NORMAL:{t:'Normal',a:'Trade your usual iron condor rules.',d:['Standard lot size','Usual wing width and strike distance','No extra hedge needed from this indicator']},
 CAUTION:{t:'Caution',a:'Reduce aggression and avoid very tight strikes.',d:['Prefer normal size only if premiums pay for the risk','Avoid short strikes close to spot','Check the signal list before holding overnight']},
 HIGH:{t:'High',a:'Reduce lot size, widen the wings, avoid overnight short-option risk.',d:['Cut lot size','Widen wings / move short strikes further out','Prefer closing short options before the market closes']},
 AVOID:{t:'Avoid fresh narrow IC',a:'Avoid new narrow condors and review hedge or exit rules.',d:['No fresh narrow iron condors','Review existing positions against your hedge / exit rules','Gap risk is the concern, not direction']}};
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const ago=t=>{if(!t)return'never';const s=Math.round((Date.now()-new Date(t))/1000);return s<45?'just now':s<3600?Math.round(s/60)+' min ago':s<86400?Math.round(s/3600)+' h ago':Math.round(s/86400)+' d ago'};
const when=t=>new Date(t).toLocaleString([], {day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
let AUTH=false;
async function api(u,opt){const r=await fetch(u,opt);if(r.status===401){showLogin();throw new Error('login')}if(!r.ok)throw new Error(u+' '+r.status);return r.json()}
function showLogin(){$('#login').style.display='grid';setTimeout(()=>$('#pw').focus(),50)}
async function doLogin(){const r=await fetch('/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('#pw').value})});
 if(r.ok){$('#login').style.display='none';$('#pw').value='';route()}else{$('#lerr').textContent=r.status===429?'Too many attempts. Wait a few minutes.':'Wrong password'}}
$('#lf').onsubmit=e=>{e.preventDefault();doLogin()};
$('#logout').onclick=async e=>{e.preventDefault();await fetch('/auth/logout',{method:'POST'});location.reload()};
// ---------- components
function ring(score,label,size=170,w=9){const r=size/2-w-1,c=2*Math.PI*r;return `<svg width="${size}" height="${size}" style="transform:rotate(-90deg)"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="${css('--line')}" stroke-width="${w}"/><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="${colr(label)}" stroke-width="${w}" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-score/100)}" style="transition:stroke-dashoffset 1.1s cubic-bezier(.2,.8,.2,1)"/></svg>`}
function spark(a,col){if(!a||a.length<2)return '<div class="empty" style="padding:8px 0">History builds as the agent runs</div>';const w=300,h=46,m=Math.max(100,...a);const p=a.map((v,i)=>[i/(a.length-1)*w,h-2-(v/m)*(h-6)]);const d='M'+p.map(x=>x.map(n=>n.toFixed(1)).join(',')).join('L');return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="${d}L${w},${h}L0,${h}Z" fill="${col}" opacity=".12"/><path d="${d}" fill="none" stroke="${col}" stroke-width="1.8"/></svg>`}
function chart(points,marker){ // points [{t,score,label}]
 if(!points||points.length<2)return '<div class="empty">Not enough history yet. The chart fills in as the agent keeps running.</div>';
 const W=900,H=210,P=28,t0=+new Date(points[0].t),t1=+new Date(points.at(-1).t)||t0+1,X=t=>P+(new Date(t)-t0)/(t1-t0||1)*(W-P-8),Y=v=>H-22-(v/100)*(H-34);
 const bands=[[0,30,'--normal'],[31,55,'--caution'],[56,75,'--high'],[76,100,'--avoid']].map(b=>`<rect x="${P}" y="${Y(b[1])}" width="${W-P-8}" height="${Y(b[0])-Y(b[1])}" fill="${css(b[2])}" opacity=".06"/>`).join('');
 const d='M'+points.map(p=>X(p.t).toFixed(1)+','+Y(p.score).toFixed(1)).join('L');
 const grid=[0,30,55,75,100].map(v=>`<text x="2" y="${Y(v)+3}" fill="${css('--mute')}" font-size="9" font-family="monospace">${v}</text>`).join('');
 const mk=marker!=null?`<line x1="${X(marker)}" x2="${X(marker)}" y1="8" y2="${H-22}" stroke="${css('--accent')}" stroke-dasharray="3 3"/>`:'';
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${bands}${grid}<path d="${d}" fill="none" stroke="${css('--accent')}" stroke-width="2"/>${mk}<text x="${P}" y="${H-5}" fill="${css('--mute')}" font-size="10" font-family="monospace">${when(points[0].t)}</text><text x="${W-8}" y="${H-5}" text-anchor="end" fill="${css('--mute')}" font-size="10" font-family="monospace">${when(points.at(-1).t)}</text></svg>`}
function badge(l){return `<span class="badge" style="--c:${colr(l)}">${esc(l)}</span>`}
function narrative(type,ev,region){ // explanation built only from the stored evidence
 const n=ev.count, base=ev.baseline_per_hour_24h;
 const b=base!=null?` Over the previous 24 hours the feed averaged ${base} per hour in this zone.`:'';
 const m={gps_jamming_cluster:`${n} aircraft inside the zone reported degraded navigation accuracy (NACp 5 or worse) in the last 60 minutes.${b} This is a proxy for GPS interference, not confirmed jamming.`,
  military_spike:`The community ADS-B military feed showed ${n} military-flagged aircraft in the zone in the last 60 minutes.${b} Aircraft that do not broadcast are not visible to this feed.`,
  tanker_dark_gap:`${n} tanker AIS anomalies (silent after being underway, stopped in a chokepoint, or changed identity) in the last 2 hours. AIS coverage is from terrestrial receivers, so a gap can also be a coverage edge.`,
  conflict_news_spike:`${n} conflict-coded articles or events were mapped to this zone in the last 60 minutes by GDELT.`,
  crude_confirmation:`Brent crude is up ${ev.pct!=null?ev.pct.toFixed(2):''}% versus the previous close. Used only as market confirmation of an OSINT signal.`,
  vix_confirmation:`India VIX is up ${ev.pct!=null?ev.pct.toFixed(2):''}% versus the previous close. Used only as market confirmation of an OSINT signal.`};
 return m[type]||ev.reason||''}
// ---------- router
let cleanup=null;const routes={};
function route(){if(cleanup){cleanup();cleanup=null}const h=(location.hash||'#/').slice(2)||'overview';
 document.querySelectorAll('nav.side a[data-r]').forEach(a=>a.classList.toggle('on',a.dataset.r===h||(h===''&&a.dataset.r==='overview')));
 const [name,arg]=h.split('/');const fn=routes[name==='region'?'region':name]||routes.overview;const v=$('#view');v.className='';void v.offsetWidth;v.className='enter';v.innerHTML=SKEL;window.scrollTo(0,0);v.scrollTop=0;
 Promise.resolve(fn(v,arg)).catch(e=>{if(e.message!=='login')v.innerHTML=`<div class="card empty">Could not load this page (${esc(e.message)}). The agent may be starting up. Retrying on next refresh.</div>`})}
const SKEL='<div class="skel"><div class="sk t"></div><div class="sk s"></div><div class="sk3"><div class="sk"></div><div class="sk"></div><div class="sk"></div></div><div class="sk big"></div></div>';
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches||document.documentElement.classList.contains('noanim');
function moveInd(){const ind=$('#navind'),a=document.querySelector('nav.side a.on');if(!ind||!a||getComputedStyle(ind).display==='none')return;ind.style.transform=`translateY(${a.offsetTop}px)`;ind.style.height=a.offsetHeight+'px';ind.style.opacity=1}
function setActive(){const h=(location.hash||'#/').slice(2)||'overview';document.querySelectorAll('nav.side a[data-r]').forEach(a=>a.classList.toggle('on',a.dataset.r===(h.split('/')[0]==='region'?h:h.split('/')[0])||(h===''&&a.dataset.r==='overview')));moveInd()}
let firstNav=true;
function nav(){setActive();if(firstNav||reduce){firstNav=false;route();return}const v=$('#view');v.classList.remove('enter');v.classList.add('leave');setTimeout(route,170)}
window.addEventListener('resize',moveInd);
window.onhashchange=nav;
// ---------- pages
routes.overview=async v=>{
 const d=await api('/api/overview');const lab=d.overall;
 v.innerHTML=`<h1>Overview</h1><p class="sub">Geopolitical volatility and gap-risk radar for NIFTY weekly option sellers. Updates every 5 minutes.</p>
 <div class="grid2 stag"><div class="card"><div class="eyebrow">Current stance</div><div class="stance" style="margin-top:12px"><div class="gauge">${ring(d.max_score,lab)}<div class="n"><div>${d.max_score}<small>OUT OF 100</small></div></div></div>
 <div><div class="big" style="color:${colr(lab)}">${PLAY[lab].t}</div><p class="lead">${PLAY[lab].a}</p></div></div></div>
 <div class="card"><div class="eyebrow">Market confirmation</div><div class="market" style="margin-top:14px">${tile('Brent crude',d.market.brent)}${tile('India VIX',d.market.india_vix)}</div></div></div>
 <div class="regions stag">${d.regions.map(r=>{const c=colr(r.label),cc=r.live_counts;return `<a href="#/region/${r.region}" style="text-decoration:none;color:inherit"><div class="card rc" style="--c:${c}"><div class="top"><h3>${esc(r.name)}</h3>${badge(r.label)}</div><div class="sc">${r.score}<small> / 100 · x${r.multiplier}</small></div>${spark(r.spark,c)}<div class="chips" style="--c:${c}">${r.active_signals.length?r.active_signals.map(a=>`<span class="chip"><b style="color:${c}">${SIG[a.type]}</b> ${a.score}</span>`).join(''):'<span class="chip">No active signals</span>'}</div>
 <div class="counts"><div>${cc.gps_aircraft}<span>GPS degraded</span></div><div>${cc.military_aircraft}<span>Military</span></div><div>${cc.news_articles}<span>News</span></div><div>${d.ais_enabled?cc.ais_anomalies:'-'}<span>AIS</span></div></div></div></a>`}).join('')}</div>
 <div class="grid2"><div class="card"><div class="eyebrow">Latest alerts</div><div class="tl">${d.alerts.length?d.alerts.slice(0,5).map(alertRow).join(''):'<div class="empty">No alerts yet. An alert needs two independent signal types in one region, so a quiet period is expected behaviour.</div>'}</div></div>
 <div class="card"><div class="eyebrow">What this means for your iron condor</div><div style="margin-top:12px">${PLAY[lab].d.map((x,i)=>`<div class="step"><i>${i+1}</i><div>${x}</div></div>`).join('')}</div><p class="lead" style="margin-top:10px;font-size:12px">Volatility and gap-risk indicator only. It does not predict direction.</p></div></div>`;
 setUpd(d.now);
 api('/api/context').then(c=>{const box=document.createElement('div');box.className='card';box.style.marginTop='20px';box.innerHTML=`<div class="eyebrow">Risk now vs usual</div><div class="ctx">${c.regions.map(x=>x.ready?`<div class="cx"><h4>${esc(x.name)}</h4><div class="bar"><i style="width:${x.percentile}%"></i><b style="left:${x.percentile}%"></b></div><p>Score ${x.current} is higher than or equal to <strong>${x.percentile}%</strong> of the ${x.n.toLocaleString()} readings stored over ${Math.round(x.hours/24)} days. Median ${x.median}, 90th percentile ${x.p90}, highest ${x.max}.</p></div>`:`<div class="cx"><h4>${esc(x.name)}</h4><div class="bar off"></div><p>Building a baseline: ${x.n} readings over ${x.hours} hours. A percentile needs at least ${c.min_readings} readings over ${c.min_hours} hours, so none is shown yet and nothing is estimated.</p></div>`).join('')}</div><p style="color:var(--mute);font-size:12.5px;margin-top:14px">Compared with this agent's own stored history only. It is not a market-wide or multi-year measure.</p>`;v.appendChild(box)}).catch(()=>{});
};
function tile(n,m){if(!m)return `<div class="tile"><div class="eyebrow">${n}</div><div class="v">-</div><div class="s">waiting for first reading</div></div>`;const up=m.pct>=0;return `<div class="tile"><div class="eyebrow">${n}</div><div class="v">${Number(m.last).toFixed(2)}</div><div class="d ${up?'up':'dn'}">${up?'+':''}${Number(m.pct).toFixed(2)}% vs prev close</div><div class="s">${m.stale?'Market closed, last session value':'Live'} · ${esc(m.symbol)} · ${ago(m.bar_time)}</div></div>`}
function alertRow(a){const l=a.kind==='morning'?'MORNING':a.kind==='system_warning'?'SYSTEM':a.label;return `<div class="al" style="--c:${colr(l)}" onclick="openAlert('${a.id}')"><div class="b"></div><div><h4>${a.kind==='morning'?'Morning summary':a.kind==='test'?'Test alert':a.kind==='system_warning'?'System warning - feed stale':a.label+' - '+esc(RN[a.region]||a.region)}</h4><p>${ago(a.sent_at||a.t)} · score ${a.score} · ${a.status}</p></div></div>`}
window.openAlert=async id=>{const a=await api('/alerts/'+id);
 const ev=(a.evidence||[]).map(e=>`<div class="eyebrow" style="margin-top:14px">${esc(SIG[e.signal]||e.signal)} · signal score ${e.score}</div><p style="margin:6px 0;font-size:13px">${esc(narrative(e.signal,e.evidence,a.region))}</p>`+e.events.slice(0,5).map(x=>`<div class="ev">${esc(x.source)} · ${esc(x.detail||x.type)} · ${ago(x.time)}</div>`).join('')).join('');
 $('#dlgBody').innerHTML=`<div class="eyebrow">${a.label} · ${esc(RN[a.region]||a.region)} · ${new Date(a.sent_at).toLocaleString()} · ${a.status}</div><pre>${esc(a.message)}</pre>${ev}`;$('#dlg').showModal()
};
routes.region=async(v,r)=>{const d=await api('/api/region/'+r);const c=d.current,lab=c?c.label:'NORMAL',sc=c?c.score:0;
 v.innerHTML=`<h1>${esc(d.name)}</h1><p class="sub">${esc(d.why)} · region multiplier x${d.multiplier} · box ${d.bbox.join(', ')}</p>
 <div class="grid2 stag"><div class="card"><div class="eyebrow">Risk now</div><div class="stance" style="margin-top:12px"><div class="gauge">${ring(sc,lab)}<div class="n"><div>${sc}<small>OUT OF 100</small></div></div></div><div><div class="big" style="color:${colr(lab)}">${PLAY[lab].t}</div><p class="lead">${PLAY[lab].a}</p></div></div></div>
 <div class="card"><div class="eyebrow">Active signals explained</div><div style="margin-top:8px">${c&&c.active_signals.length?c.active_signals.map(a=>`<div class="step"><i style="font-size:15px;width:auto;min-width:40px">${a.score}</i><div><b>${SIG[a.type]}</b><div style="color:var(--mute);font-size:12.5px;margin-top:3px">${esc(a.evidence)}</div></div></div>`).join(''):'<div class="empty">No active signals in this zone right now.</div>'}</div></div></div>
 <div class="card" style="margin-bottom:20px"><div class="eyebrow">Risk score, last 72 hours</div>${chart(d.history)}</div>
 <div class="grid2"><div class="card"><div class="eyebrow">Signal history</div><table style="margin-top:8px"><tr><th>When</th><th>Signal</th><th>Score</th></tr>${d.signals.slice(0,12).map(g=>`<tr><td>${ago(g.t)}</td><td>${SIG[g.type]}<div style="color:var(--mute);font-size:12px">${esc(g.reason)}</div></td><td>${g.score}</td></tr>`).join('')||'<tr><td colspan=3 class="empty">No signals recorded yet</td></tr>'}</table></div>
 <div class="card"><div class="eyebrow">Latest headlines</div><div class="news" style="margin-top:8px">${d.news.slice(0,8).map(h=>`<a href="${esc(h.url)}" target="_blank" rel="noopener">${esc(h.title)}<span>${esc(h.domain)} · ${ago(h.t)}</span></a>`).join('')||'<div class="empty">No conflict-coded news in the stored window</div>'}</div></div></div>`;
 setUpd(c&&c.t)};
let MAP=null,LIVE={ac:new Map(),ves:new Map(),layer:null,all:false,poll:null,tween:null};
function planeIcon(c,sz,rot){return L.divIcon({className:'',iconSize:[sz,sz],iconAnchor:[sz/2,sz/2],html:`<svg width="${sz}" height="${sz}" viewBox="0 0 20 20" style="transform:rotate(${rot||0}deg);display:block"><path d="M10 1l3 8 6 3v2l-6-1.5L12 18l2 1v1l-4-1-4 1v-1l2-1-1-4.5L1 14v-2l6-3z" fill="${c}" stroke="rgba(0,0,0,.45)" stroke-width=".6"/></svg>`})}
function proj(a,dt){if(!a.gs||a.trk==null||dt<=0)return[a.lat,a.lon];const d=a.gs*0.514444*dt/111320,r=a.trk*Math.PI/180;return[a.lat+d*Math.cos(r),a.lon+d*Math.sin(r)/Math.cos(a.lat*Math.PI/180)]}
async function pollLive(){let d;try{d=await api('/api/live')}catch(e){return}if(!MAP||!LIVE.layer)return;
 const seen=new Set(),nowS=Date.now()/1000;let nd=0,nm=0;
 for(const a of d.aircraft){if(!LIVE.all&&!a.deg&&!a.mil)continue;seen.add(a.hex);a.base=nowS;const col=a.deg?'#ff4d5e':a.mil?'#4ea1ff':'#9aa0b4',sz=a.deg?20:a.mil?18:11;a.deg?nd++:a.mil?nm++:0;let m=LIVE.ac.get(a.hex);
  if(!m){m={a,mk:L.marker([a.lat,a.lon],{icon:planeIcon(col,sz,a.trk),keyboard:false,opacity:a.deg||a.mil?1:.55}).addTo(LIVE.layer),cur:[a.lat,a.lon],col};m.mk.bindTooltip('',{direction:'top'});LIVE.ac.set(a.hex,m)}
  else{m.a=a;if(m.col!==col){m.mk.setIcon(planeIcon(col,sz,a.trk));m.col=col}else{const el=m.mk.getElement();if(el)el.firstChild.style.transform=`rotate(${a.trk||0}deg)`}}
  m.mk.setTooltipContent(`${a.deg?'Degraded GPS accuracy · ':''}${a.mil?'Military flag · ':''}${esc(a.call||a.hex)}${a.t?' · '+esc(a.t):''}<br>${a.alt?Math.round(a.alt)+' ft · ':''}${a.gs?Math.round(a.gs)+' kt':''}`)}
 for(const [h,m] of LIVE.ac)if(!seen.has(h)){LIVE.layer.removeLayer(m.mk);LIVE.ac.delete(h)}
 const vs=new Set();for(const x of d.vessels||[]){vs.add(x.mmsi);let m=LIVE.ves.get(x.mmsi);const col=x.tanker?'#f5b544':'#6fd3c7';if(!m){m={mk:L.circleMarker([x.lat,x.lon],{radius:x.tanker?5:3,color:col,fillColor:col,fillOpacity:.8,weight:1}).addTo(LIVE.layer)};LIVE.ves.set(x.mmsi,m)}else m.mk.setLatLng([x.lat,x.lon]);m.mk.bindTooltip(`${esc(x.name||x.mmsi)}${x.tanker?' · tanker':''}${x.sog!=null?' · '+x.sog.toFixed(1)+' kt':''}`)}
 for(const [k,m] of LIVE.ves)if(!vs.has(k)){LIVE.layer.removeLayer(m.mk);LIVE.ves.delete(k)}
 const ages=Object.values(d.sweeps).map(x=>x.last_sweep?Math.round((Date.now()-new Date(x.last_sweep))/1000):null),el=$('#liveinfo');
 if(el)el.textContent=ages.some(x=>x==null)?'warming up…':`${nd} with degraded GPS accuracy · ${nm} military-flagged · ${(d.vessels||[]).length} vessels · zones last refreshed ${Math.min(...ages)}-${Math.max(...ages)} s ago`}
async function mountMap(el,height){MAP=L.map(el,{zoomControl:false,attributionControl:false}).setView([24,55],4);const dark=css('--map')==='dark';
 L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/'+(dark?'World_Dark_Gray_Base':'World_Light_Gray_Base')+'/MapServer/tile/{z}/{y}/{x}',{maxZoom:9,className:'tiles-clean'}).addTo(MAP);
 L.control.attribution({position:'bottomleft',prefix:false}).addAttribution('Tiles © Esri, HERE, Garmin, OpenStreetMap contributors').addTo(MAP);L.control.zoom({position:'bottomright'}).addTo(MAP);
 LIVE.layer=L.layerGroup().addTo(MAP);LIVE.ac=new Map();LIVE.ves=new Map();
 const m=await api('/api/map');for(const b of Object.values(m.regions))L.rectangle([[b[0],b[2]],[b[1],b[3]]],{color:css('--accent'),weight:1,fill:false,dashArray:'4 6',opacity:.6}).addTo(LIVE.layer);
 m.points.filter(p=>p.type==='ais_dark_gap').forEach(p=>L.circleMarker([p.lat,p.lon],{radius:8,color:'#f5b544',fillOpacity:.3,weight:2}).bindTooltip('Tanker AIS anomaly').addTo(LIVE.layer));
 setTimeout(()=>{MAP.invalidateSize();MAP.fitBounds([[10,32],[38,78]])},60);
 await pollLive();LIVE.poll=setInterval(pollLive,5000);
 LIVE.tween=setInterval(()=>{const t=Date.now()/1000;for(const m of LIVE.ac.values()){const a=m.a,[la,lo]=proj(a,Math.min(90,t-a.base+(a.age||0)));m.cur=[m.cur[0]+(la-m.cur[0])*.35,m.cur[1]+(lo-m.cur[1])*.35];m.mk.setLatLng(m.cur)}},250);
 cleanup=()=>{clearInterval(LIVE.poll);clearInterval(LIVE.tween);MAP.remove();MAP=null}}
routes.map=async v=>{v.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:end"><div><h1>Live map</h1><p class="sub" id="liveinfo" style="margin-bottom:12px">warming up…</p></div><label style="color:var(--mute);font-size:13px;cursor:pointer;margin-bottom:12px"><input type="checkbox" id="allT"> show all traffic</label></div><div id="bigmap" class="mapfull"></div>
 <div class="legend"><span><i style="background:#ff4d5e"></i>Degraded GPS accuracy (proxy for interference)</span><span><i style="background:#4ea1ff"></i>Military-flagged aircraft</span><span><i style="background:#f5b544"></i>Tanker</span><span><i style="background:#6fd3c7"></i>Vessel</span></div>
 <p class="lead" style="font-size:12px;margin-top:10px;max-width:none">Positions come from a server cache of public ADS-B feeds, refreshed every 15-60 s per zone, and glide between refreshes using each aircraft's reported speed and heading. A zone showing none means the feed shows none, not that none exist.</p>`;
 LIVE.all=false;$('#allT').onchange=e=>{LIVE.all=e.target.checked;pollLive()};await mountMap($('#bigmap'))};
routes.signals=async v=>{v.innerHTML=`<h1>Signals explorer</h1><p class="sub">Every signal the extractors produced, newest first.</p><div class="bar"><select id="fr"><option value="">All regions</option>${Object.keys(RN).slice(0,3).map(k=>`<option value="${k}">${RN[k]}</option>`).join('')}</select><select id="ft"><option value="">All types</option>${Object.entries(SIG).map(([k,x])=>`<option value="${k}">${x}</option>`).join('')}</select><select id="fh"><option value="24">24 h</option><option value="48" selected>48 h</option><option value="168">7 days</option></select></div><div class="card" id="tbl"></div>`;
 const load=async()=>{const q=new URLSearchParams({hours:$('#fh').value});if($('#fr').value)q.set('region',$('#fr').value);if($('#ft').value)q.set('type',$('#ft').value);const d=await api('/api/signals?'+q);
  $('#tbl').innerHTML=d.length?`<table><tr><th>When</th><th>Region</th><th>Signal</th><th>Score</th><th>Evidence</th></tr>${d.map(g=>`<tr><td>${when(g.t)}</td><td>${esc(RN[g.region]||g.region)}</td><td>${SIG[g.type]}</td><td>${g.score}</td><td style="color:var(--mute)">${esc(g.evidence.reason||'')}</td></tr>`).join('')}</table>`:'<div class="empty">No signals in this window. Signals only appear when a rule threshold is met.</div>'};
 ['fr','ft','fh'].forEach(i=>$('#'+i).onchange=load);load()};
routes.alerts=async v=>{v.innerHTML=`<h1>Alerts</h1><p class="sub">Click a row for the evidence behind it.</p><div class="bar"><select id="fl"><option value="">All bands</option><option>CAUTION</option><option>HIGH</option><option>AVOID</option></select><a class="btn ghost" href="/alerts.csv" style="text-decoration:none">Export CSV</a></div><div class="card" id="tbl"></div>`;
 const load=async()=>{const d=await api('/api/alerts'+($('#fl').value?'?label='+$('#fl').value:''));$('#tbl').innerHTML=d.length?`<table><tr><th>When</th><th>Region</th><th>Band</th><th>Score</th><th>Status</th><th>Type</th></tr>${d.map(a=>`<tr class="click" onclick="openAlert('${a.id}')"><td>${when(a.t)}</td><td>${esc(RN[a.region]||a.region)}</td><td>${badge(a.kind==='morning'?'MORNING':a.kind==='system_warning'?'SYSTEM':a.label)}</td><td>${a.kind==='system_warning'?'-':a.score}</td><td>${a.status}</td><td>${a.kind==='system_warning'?'system warning · feed stale':a.kind}${a.escalation?' · escalation':''}</td></tr>`).join('')}</table>`:'<div class="empty">No alerts yet. An alert needs two independent signal types in one region; quiet is the normal state.</div>'};$('#fl').onchange=load;load()};
routes.replay=async v=>{const ds=await Promise.all(Object.keys(RN).slice(0,3).map(r=>api('/api/region/'+r+'?hours=336')));
 const pts=ds[0].history;if(pts.length<2){v.innerHTML='<h1>Risk replay</h1><div class="card empty">Replay needs stored history. It starts filling as soon as the agent has run for a few cycles.</div>';return}
 v.innerHTML=`<h1>Risk replay</h1><p class="sub">Scrub through stored risk snapshots to see what the radar showed at any past moment.</p><div class="card"><input type="range" id="rs" min="0" max="${pts.length-1}" value="${pts.length-1}" style="width:100%"><div class="eyebrow" id="rt" style="margin:10px 0"></div><div class="grid3" id="rg" style="margin:0"></div></div><div class="card" style="margin-top:20px"><div class="eyebrow">Hormuz score over the stored window</div><div id="rc"></div></div>`;
 const at=i=>{const t=+new Date(pts[i].t);$('#rt').textContent=new Date(pts[i].t).toLocaleString();$('#rg').innerHTML=ds.map(d=>{let best=d.history[0];for(const p of d.history)if(Math.abs(new Date(p.t)-t)<Math.abs(new Date(best.t)-t))best=p;return `<div class="tile"><div class="eyebrow">${esc(d.name)}</div><div class="v" style="color:${colr(best.label)}">${best.score}</div><div class="d">${best.label}</div></div>`}).join('');$('#rc').innerHTML=chart(pts,pts[i].t)};
 $('#rs').oninput=e=>at(+e.target.value);at(pts.length-1)};
routes.news=async v=>{v.innerHTML=`<h1>Conflict news</h1><p class="sub">GDELT articles and geocoded events mapped to the three zones.</p><div class="bar"><select id="fr"><option value="">All regions</option>${Object.keys(RN).slice(0,3).map(k=>`<option value="${k}">${RN[k]}</option>`).join('')}</select></div><div class="card news" id="nl"></div>`;
 const load=async()=>{const d=await api('/api/news'+($('#fr').value?'?region='+$('#fr').value:''));$('#nl').innerHTML=d.length?d.map(h=>`<a href="${esc(h.url)}" target="_blank" rel="noopener">${esc(h.title)}<span>${esc(h.domain)} · ${esc(RN[h.region])} · ${ago(h.t)} · ${esc(h.feed||'')}</span></a>`).join(''):'<div class="empty">Nothing in the last 12 hours</div>'};$('#fr').onchange=load;load()};
routes.feeds=async v=>{const d=await api('/api/overview');v.innerHTML=`<h1>Feed health</h1><p class="sub">Every collector run is recorded. A feed showing nothing is different from a feed that is down.</p><div class="feeds stag">${d.feeds.map(f=>`<div class="feed"><b><span class="dot ${f.ok?'':'bad'}"></span>${esc(f.feed)}</b><small>${f.last_ok?'last ok '+ago(f.last_ok):(f.messages!==undefined?f.messages+' messages':'no run yet')}</small><small>${f.events_last_run!==undefined?f.events_last_run+' events last run · ':''}${f.duration_s!=null?f.duration_s+' s · ':''}${f.success_rate_24h!=null?f.success_rate_24h+'% ok in 24 h':''}</small>${f.error?`<small style="color:var(--avoid)">${esc(f.error.slice(0,120))}</small>`:''}</div>`).join('')}</div>
 <div class="card" style="margin-top:20px"><div class="eyebrow">Sources</div><div class="kv" style="margin-top:12px"><b>Aircraft, GPS accuracy, military flag</b><span>adsb.lol, fallback adsb.fi (public ADS-B)</span><b>Conflict news</b><span>GDELT DOC API, fallback GDELT 15-minute event files</span><b>Brent, India VIX</b><span>Yahoo Finance chart API, fallback NSE</span><b>Vessels</b><span>aisstream.io ${d.ais_enabled?'(connected)':'(needs AISSTREAM_API_KEY)'}</span></div></div>`;setUpd(d.now)};
routes.settings=async v=>{const [s,E]=await Promise.all([api('/api/settings'),api('/api/settings/editable')]);
 const grp=(t,f)=>E.fields.filter(x=>f(x.key));
 const inp=x=>{const id='f_'+x.key;if(x.type==='bool')return `<label class="sw"><input type="checkbox" data-k="${x.key}" ${x.value?'checked':''}> ${x.value?'On':'Off'}</label>`;
  if(x.type==='list3')return [0,1,2].map(i=>`<input class="num" data-k="${x.key}" data-i="${i}" value="${x.value[i]}" inputmode="decimal">`).join('');
  return `<input class="num" data-k="${x.key}" value="${x.value}" inputmode="decimal">`};
 const rows=fs=>fs.map(x=>`<div class="frow"><div><b>${esc(x.label)}</b><small>default ${Array.isArray(x.default)?x.default.join(' / '):x.default}${x.min!=null&&x.type!=='list3'?` · allowed ${x.min} to ${x.max}`:''}</small></div><div class="fin ${x.changed?'chg':''}">${inp(x)}</div></div>`).join('');
 const fmt=x=>Array.isArray(x)?x.join(' / '):String(x);
 v.innerHTML=`<h1>Settings</h1><p class="sub">Thresholds and weights that drive the score. Changes apply on the next scoring cycle and are written to the change log.</p>
 <div class="grid2"><div class="card"><div class="eyebrow">Delivery</div><div class="kv" style="margin-top:12px"><b>Telegram</b><span>${s.telegram.ready?'ready':'not connected'} (token ${s.telegram.token_set?'set':'missing'}, chat id ${s.telegram.chat_set?'set':'missing'})</span><b>LLM analyst note</b><span>${esc(s.llm_provider)}</span><b>AIS</b><span>${s.ais_enabled?'on':'off (no key)'}</span><b>Live layer</b><span>${s.live_layer?'on':'off'}, zone sweeps every ${Object.entries(s.live_tiers_s).map(([k,x])=>k+' '+x+'s').join(', ')}</span><b>Morning summary</b><span>${s.alerts.morning_summary_time_ist} IST, Mon-Fri</span><b>Retention</b><span>${s.retention_days} days</span></div><div style="margin-top:16px"><button class="btn" id="tt">Send test alert</button> <span id="tr" style="color:var(--mute);font-size:13px;margin-left:8px"></span></div></div>
 <div class="card"><div class="eyebrow">Admin</div><p class="lead" style="margin:12px 0">${E.editing_enabled?'Signed in as admin. Every change is logged with time, old value and new value.':'Editing is disabled because ADMIN_PASSWORD is not set on this server.'}</p><div class="bar" style="margin:0"><button class="btn" id="sv" ${E.editing_enabled?'':'disabled'}>Save changes</button><button class="btn ghost" id="rs" ${E.editing_enabled?'':'disabled'}>Reset to defaults</button><span id="sm" style="font-size:13px;color:var(--mute)"></span></div></div></div>
 <div class="grid2" style="margin-top:20px"><div class="card"><div class="eyebrow">Signal weights (points)</div><div class="fl">${rows(grp(0,k=>k.startsWith('weights.')))}</div><div class="eyebrow" style="margin-top:22px">Risk bands (score where the band starts)</div><div class="fl">${rows(grp(0,k=>k.startsWith('bands.')))}</div><div class="eyebrow" style="margin-top:22px">Region multipliers</div><div class="fl">${rows(grp(0,k=>k.includes('.multiplier')))}</div></div>
 <div class="card"><div class="eyebrow">Detection rules</div><div class="fl">${rows(grp(0,k=>k.startsWith('rules.')))}</div><div class="eyebrow" style="margin-top:22px">Alerts</div><div class="fl">${rows(grp(0,k=>k.startsWith('alerts.')))}</div></div></div>
 <div class="card" style="margin-top:20px"><div class="eyebrow">Change log</div>${E.log.length?`<table><tr><th>When</th><th>Who</th><th>Setting</th><th>Old</th><th>New</th></tr>${E.log.map(c=>`<tr><td>${new Date(c.t).toLocaleString()}</td><td>${esc(c.actor)}</td><td>${esc(c.label)}${c.note?' ('+esc(c.note)+')':''}</td><td>${esc(fmt(c.old))}</td><td>${esc(fmt(c.new))}</td></tr>`).join('')}</table>`:'<div class="empty">No changes yet. Everything runs on the shipped defaults.</div>'}</div>`;
 const collect=()=>{const o={};$$('[data-k]').forEach(el=>{const k=el.dataset.k;if(el.type==='checkbox'){o[k]=el.checked}else if(el.dataset.i!==undefined){(o[k]=o[k]||[])[+el.dataset.i]=el.value}else o[k]=el.value});return o};
 $('#sv').onclick=async()=>{const all=collect(),ch={};for(const x of E.fields){const n=all[x.key];const cur=x.type==='bool'?n:x.type==='list3'?n.map(Number):Number(n);if(JSON.stringify(cur)!==JSON.stringify(x.value))ch[x.key]=cur}
  if(!Object.keys(ch).length){$('#sm').textContent='Nothing changed';return}
  const r=await fetch('/api/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({changes:ch})});const j=await r.json();
  if(!r.ok){$('#sm').style.color='var(--avoid)';$('#sm').textContent=j.detail||'Could not save';return}toast(j.applied.length+' setting(s) saved');routes.settings(v)};
 $('#rs').onclick=async()=>{if(!confirm('Reset every setting to the shipped defaults?'))return;const r=await fetch('/api/settings/reset',{method:'POST'});if(r.ok){toast('Reset to defaults');routes.settings(v)}};
 $('#tt').onclick=async()=>{$('#tr').textContent='sending…';const r=await fetch('/alerts/test',{method:'POST',headers:{'content-type':'application/json'},body:'{}'});$('#tr').textContent=r.ok?'sent (status: '+(await r.json()).status+')':r.status===429?'wait 30 seconds between tests':'failed'}};
routes.scenario=async v=>{const P=await api('/api/scenario/presets'),S=await api('/api/settings');const W=S.weights;let cur=null;
 const nm=t=>SIG[t]||t;
 v.innerHTML=`<div class="bar noprint" style="justify-content:space-between"><div><h1>Scenario Lab</h1><p class="sub" style="margin:0">Stress the radar with a hypothetical shock and see how the live engine would react. Your real current signals stay in place underneath.</p></div><button class="btn" id="ex" disabled>Export executive brief (PDF)</button></div>
 <div class="grid2" style="margin-top:20px;align-items:start"><div class="card noprint"><div class="eyebrow">1 · Pick a scenario</div><div class="chips" style="margin:12px 0 18px">${Object.entries(P).map(([k,p])=>`<button class="chip" data-p="${k}">${esc(p.name)}</button>`).join('')}</div>
  <div class="eyebrow">2 · Or build your own</div><div class="bar" style="margin:10px 0"><select id="sr">${Object.keys(RN).slice(0,3).map(k=>`<option value="${k}">${RN[k]}</option>`).join('')}</select></div>
  ${Object.keys(W).map(t=>`<label class="tg"><span>${esc(nm(t))}<small>${W[t]} pts</small></span><input type="checkbox" data-t="${t}"></label>`).join('')}
  <div style="margin-top:16px"><div class="eyebrow">India VIX shock: <b id="vl" style="color:var(--ink)">+0</b> points</div><input type="range" id="vs" class="rng" min="0" max="20" step="1" value="0" style="width:100%;margin-top:8px"></div>
  <button class="btn" id="run" style="margin-top:18px;width:100%">Run scenario</button></div>
 <div id="res"><div class="card"><div class="empty">Choose a scenario on the left. Results appear here.</div></div></div></div>`;
 const setP=k=>{const p=P[k];$('#sr').value=p.region;$$('[data-t]').forEach(c=>c.checked=p.signals.includes(c.dataset.t));$('#vs').value=p.vix_pts;$('#vl').textContent='+'+p.vix_pts;$$('.chip').forEach(c=>c.classList.toggle('on',c.dataset.p===k));cur=k};
 $$('.chip').forEach(c=>c.onclick=()=>{setP(c.dataset.p);run()});$('#vs').oninput=e=>{$('#vl').textContent='+'+e.target.value;$$('.chip').forEach(c=>c.classList.remove('on'))};
 $$('[data-t]').forEach(c=>c.onchange=()=>$$('.chip').forEach(x=>x.classList.remove('on')));
 async function run(){const sig=$$('[data-t]').filter(c=>c.checked).map(c=>c.dataset.t);if(!sig.length){toast('Pick at least one signal');return}
  const r=await fetch('/api/scenario',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({region:$('#sr').value,signals:sig,vix_pts:+$('#vs').value})});const j=await r.json();if(!r.ok){toast(j.detail||'Could not run');return}
  const B=j.before,A=j.after,st=j.strikes,story=cur&&P[cur]?P[cur].story:'Custom scenario.';
  const why=A.alert_candidate?`Two or more independent signal types, including at least one physical or news signal, would be active. The engine <b>would send an alert</b>.`:A.signal_types.length?`Not enough independent evidence. The engine <b>would not alert</b>: ${A.signal_types.length<2?'only one signal type':'market signals only count when a physical or news signal is also present'}.`:'Market-only signals do not score on their own, so the engine stays at zero.';
  $('#res').innerHTML=`<div class="printonly" style="margin-bottom:14px"><h1>Executive risk brief</h1><p class="sub">Geo-Macro Risk Agent · ${new Date().toLocaleString()} · hypothetical scenario on live data</p></div>
  <div class="card"><div class="eyebrow">${cur&&P[cur]?esc(P[cur].name):esc(j.region_name)+' · custom scenario'}</div><p class="lead" style="margin:8px 0 18px">${esc(story)}</p>
  <div class="cmp"><div><div class="eyebrow">Now (live)</div><div class="n" style="color:${colr(B.label)}">${B.score}</div>${badge(B.label)}</div><div class="arrow">→</div><div><div class="eyebrow">Scenario</div><div class="n" style="color:${colr(A.label)}">${A.score}</div>${badge(A.label)}</div></div>
  <p style="margin-top:20px;font-size:14px">${why}</p></div>
  <div class="card" style="margin-top:20px"><div class="eyebrow">Where the points come from (× ${A.multiplier} regional multiplier)</div><div style="margin-top:12px">${Object.entries(A.contributions).map(([t,x])=>`<div class="cb"><span>${esc(nm(t))}${j.added.includes(t)?' (hypothetical)':' (live)'}</span><i style="width:${Math.min(100,x*2.4)}%;${j.added.includes(t)?'':'background:var(--mute)'}"></i><b>${x}</b></div>`).join('')||'<div class="empty">No scoring signals.</div>'}</div></div>
  ${st?`<div class="card" style="margin-top:20px"><div class="eyebrow">What it means for a NIFTY 7-day iron condor (spot ${st.spot.toLocaleString('en-IN')})</div><div class="grid2" style="margin-top:14px"><div class="leg"><small>Now · ${st.now.label} · ${st.now.k}σ · VIX ${st.now.vix}</small><b>${st.now.short_put} / ${st.now.short_call}</b><i>short put / short call</i></div><div class="leg"><small>Scenario · ${st.scenario.label} · ${st.scenario.k}σ · VIX ${st.scenario.vix}</small><b style="color:${colr(st.scenario.label)}">${st.scenario.short_put} / ${st.scenario.short_call}</b><i>${st.scenario.short_call-st.scenario.short_put-(st.now.short_call-st.now.short_put)>=0?'+':''}${st.scenario.short_call-st.scenario.short_put-(st.now.short_call-st.now.short_put)} pts wider in total</i></div></div></div>`:''}
  <p class="lead" style="font-size:12px;max-width:none;margin-top:14px">Hypothetical. Signals marked hypothetical are assumed, not observed. Scores use this deployment's live weights and the same scoring code as the real radar. VIX shock is an assumption you chose. Planning aid, not a forecast or advice.</p>`;$('#ex').disabled=false};
 $('#run').onclick=run;$('#ex').onclick=()=>window.print();{const q=new URLSearchParams(location.search).get('preset');if(q&&P[q]){setP(q);run()}}setUpd(new Date().toISOString())};
routes.gaps=async v=>{v.innerHTML=`<h1>Overnight gap risk</h1><p class="sub">Iron condors cannot be adjusted while the market is shut. This page measures how far NIFTY really opened away from the previous close, over five years of actual daily data.</p><div id="gpb"><div class="empty">Loading five years of market history…</div></div>`;
 let d;try{d=await api('/api/gaps')}catch(e){$('#gpb').innerHTML='<div class="card"><div class="empty">Historical market data is unavailable right now. Nothing is estimated. Try again in a minute.</div></div>';return}
 const mx=Math.max(...d.hist.map(x=>x.n)),lab=h=>(h.lo<=-9?'below '+h.hi:h.hi>=9?'above '+h.lo:h.lo+' to '+h.hi)+'%',vs=d.vix_split,p=d.abs_percentiles;
 $('#gpb').innerHTML=`<div class="grid3 stag" style="margin-bottom:20px"><div class="tile"><div class="eyebrow">Trading days measured</div><div class="v">${d.days}</div><div class="d">${d.from} to ${d.to}</div></div><div class="tile"><div class="eyebrow">Typical gap (median)</div><div class="v">${p.p50}%</div><div class="d">9 in 10 days are under ${p.p90}%</div></div><div class="tile"><div class="eyebrow">Gap bigger than 1%</div><div class="v" style="color:var(--avoid)">${d.exceed[1].share}%</div><div class="d">${d.exceed[1].n} of ${d.days} opens. 1 in 100 days exceeds ${p.p99}%</div></div></div>
 <div class="card"><div class="eyebrow">Distribution of overnight gaps (open vs previous close)</div><div class="bt" style="margin-top:34px">${d.hist.map(x=>`<div class="g"><div class="b" style="height:${Math.max(2,x.n/mx*100)}%;background:${x.lo>=-0.5&&x.hi<=0.5?'var(--mute)':'var(--accent)'}"><em>${x.n}</em></div></div>`).join('')}</div><div class="btl">${d.hist.map(x=>`<div>${lab(x)}</div>`).join('')}</div></div>
 <div class="grid2" style="margin-top:20px"><div class="card"><div class="eyebrow">How often gaps exceed a size</div><table style="margin-top:8px"><tr><th>Gap size</th><th>Days</th><th>Share of days</th></tr>${d.exceed.map(x=>`<tr><td>over ${x.pct}%</td><td>${x.n}</td><td>${x.share}%</td></tr>`).join('')}</table>
 <div class="eyebrow" style="margin-top:22px">Gaps after a high-VIX vs low-VIX day (split at ${vs.threshold})</div><table style="margin-top:8px"><tr><th>Previous-day VIX</th><th>Days</th><th>Avg gap</th><th>Gap over 1%</th></tr><tr><td>${vs.threshold}+ (high)</td><td>${vs.high.n}</td><td>${vs.high.avg_pct}%</td><td>${vs.high.over1_pct}%</td></tr><tr><td>below ${vs.threshold}</td><td>${vs.low.n}</td><td>${vs.low.avg_pct}%</td><td>${vs.low.over1_pct}%</td></tr></table>
 <div class="eyebrow" style="margin-top:22px">By weekday (Monday includes the weekend)</div><table style="margin-top:8px"><tr><th>Day</th><th>Avg gap</th><th>Gaps over 1%</th></tr>${d.by_weekday.map(x=>`<tr><td>${x.day}</td><td>${x.avg_pct}%</td><td>${x.over1}</td></tr>`).join('')}</table></div>
 <div class="card"><div class="eyebrow">Eight largest overnight gaps</div><table style="margin-top:8px"><tr><th>Date</th><th>Gap</th><th>VIX previous day</th></tr>${d.worst.map(x=>`<tr><td>${x.date}</td><td>${x.gap_pct>0?'+':''}${x.gap_pct}%</td><td>${x.vix_prev??'-'}</td></tr>`).join('')}</table></div></div>
 <div class="card" style="margin-top:20px"><div class="eyebrow">Reading this honestly</div><ul style="margin:10px 0 0 18px;color:var(--mute);line-height:1.8;font-size:13.5px"><li>Gap = that day's real NIFTY open divided by the previous trading day's close, minus 1. Holidays and weekends are included in the gap, so Monday is a longer interval.</li><li>This is history, not a forecast. The geopolitical risk score is not shown here because it has no multi-year history.</li><li>Source: ${esc(d.source)}.</li></ul></div>`;setUpd(new Date().toISOString())};
routes.backtest=async v=>{v.innerHTML=`<h1>Strike calibration backtest</h1><p class="sub">How often would the strike rules used by Strike Guard have been breached in the real market? Five years of actual NIFTY and India VIX history, tested week by week.</p><div id="btb"><div class="empty">Loading five years of market history…</div></div>`;
 let d;try{d=await api('/api/backtest')}catch(e){$('#btb').innerHTML='<div class="card"><div class="empty">Historical market data is unavailable right now. Nothing is estimated. Try again in a minute.</div></div>';return}
 const mx=Math.max(...d.all.map(x=>x.touch_pct)),band=['NORMAL','CAUTION','HIGH','AVOID'];
 const o=d.all,hv=d.high_vix.stats;
 $('#btb').innerHTML=`<div class="grid3 stag" style="margin-bottom:20px"><div class="tile"><div class="eyebrow">Weeks tested</div><div class="v">${d.windows}</div><div class="d">${d.from} to ${d.to}</div></div><div class="tile"><div class="eyebrow">Normal-band strikes: touched in a week</div><div class="v" style="color:var(--avoid)">${o[0].touch_pct}%</div><div class="d">closed beyond them: ${o[0].close_pct}%</div></div><div class="tile"><div class="eyebrow">Avoid-band strikes: touched</div><div class="v" style="color:var(--normal,#3ddc97)">${o[3].touch_pct}%</div><div class="d">closed beyond them: ${o[3].close_pct}%</div></div></div>
 <div class="card"><div class="eyebrow">Share of weeks a short strike was breached, by distance</div>
 <div class="bt" style="margin-top:34px">${o.map((x,i)=>`<div class="g"><div class="b" style="height:${x.touch_pct/mx*100}%;background:var(--accent)"><em>${x.touch_pct}%</em></div><div class="b" style="height:${x.close_pct/mx*100}%;background:var(--mute)"><em>${x.close_pct}%</em></div></div>`).join('')}</div>
 <div class="btl">${o.map((x,i)=>`<div>${x.k}σ<br>${band[i].toLowerCase()} band rule</div>`).join('')}</div>
 <div class="legend" style="margin-top:14px"><span><i style="background:var(--accent)"></i>Touched at any point in the week (high or low)</span><span><i style="background:var(--mute)"></i>Closed beyond the strike at expiry</span></div></div>
 <div class="grid2" style="margin-top:20px"><div class="card"><div class="eyebrow">Counts</div><table style="margin-top:8px"><tr><th>Strike distance</th><th>Touched</th><th>Closed beyond</th></tr>${o.map(x=>`<tr><td>${x.k}σ</td><td>${x.touch_breach} of ${x.n} (${x.touch_pct}%)</td><td>${x.close_breach} of ${x.n} (${x.close_pct}%)</td></tr>`).join('')}</table>
 <div class="eyebrow" style="margin-top:22px">Only when VIX was high (${d.high_vix.threshold}+, top third, ${d.high_vix.n} weeks)</div><table style="margin-top:8px"><tr><th>Strike distance</th><th>Touched</th><th>Closed beyond</th></tr>${hv.map(x=>`<tr><td>${x.k}σ</td><td>${x.touch_pct}%</td><td>${x.close_pct}%</td></tr>`).join('')}</table></div>
 <div class="card"><div class="eyebrow">Largest weekly moves against the VIX-implied range</div><table style="margin-top:8px"><tr><th>Week</th><th>VIX</th><th>NIFTY move</th><th>Size vs range</th></tr>${d.worst.map(x=>`<tr><td>${x.start} to ${x.end}</td><td>${x.vix}</td><td>${x.move_pct>0?'+':''}${x.move_pct}%</td><td>${x.multiple}σ</td></tr>`).join('')}</table></div></div>
 <div class="card" style="margin-top:20px"><div class="eyebrow">Reading this honestly</div><ul style="margin:10px 0 0 18px;color:var(--mute);line-height:1.8;font-size:13.5px"><li>Each test week starts from that day's real NIFTY close and India VIX close, sets a 1σ range = spot × VIX/100 × √(7/365), and checks the next ${d.hold_days} trading days of real highs, lows and closes. Windows do not overlap.</li><li>Widening to 1.3σ, 1.7σ and 2.2σ lowers the breach rate every time, which is what the Strike Guard rule relies on. The cost is less premium collected, which this page does not model.</li><li>This tests the strike distances and the VIX range only. The geopolitical risk score has no multi-year history yet (the radar started recording when it was deployed), so it is not backtested here and no claim is made that the radar predicted any of these weeks.</li><li>Past breach rates are not a forecast. Source: ${esc(d.source)}.</li></ul></div>`;setUpd(new Date().toISOString())};
routes.strike=async v=>{let dte=7;
 v.innerHTML=`<h1>Strike Guard</h1><p class="sub">Where to place short strikes this week once the geopolitical risk score is priced in. Built from live NIFTY spot, live India VIX and this radar's own score.</p><div id="sgb"><div class="empty">Loading live quotes…</div></div>`;
 const draw=async()=>{let d;try{d=await api('/api/strikeguard?dte='+dte)}catch(e){$('#sgb').innerHTML='<div class="card"><div class="empty">Live NIFTY or VIX quote is unavailable right now. Nothing is estimated. Try again in a minute.</div></div>';return}
  const B=d.baseline,A=d.adjusted,col=colr(d.band),lo=Math.min(A.short_put,B.short_put,d.spot)-A.k*d.sigma_pts*0.5,hi=Math.max(A.short_call,B.short_call)+A.k*d.sigma_pts*0.5,W=900,x=p=>((p-lo)/(hi-lo)*W).toFixed(1);
  const bar=(y,s1,s2,c,lab,dash)=>`<rect x="${x(s1)}" y="${y}" width="${x(s2)-x(s1)}" height="22" rx="6" fill="${dash?'none':c}" fill-opacity="${dash?1:.22}" stroke="${c}" stroke-width="1.5" ${dash?'stroke-dasharray="5 4"':''}/><text x="${+x(s1)+10}" y="${y+15}" fill="${c}" font-size="11" font-family="monospace">${lab}</text>`;
  const tick=(p,c,l)=>`<line x1="${x(p)}" x2="${x(p)}" y1="26" y2="150" stroke="${c}" stroke-dasharray="3 4"/><text x="${x(p)}" y="18" fill="${c}" font-size="11" text-anchor="middle" font-family="monospace">${l} ${p}</text>`;
  $('#sgb').innerHTML=`<div class="grid3 stag" style="margin-bottom:20px"><div class="tile"><div class="eyebrow">NIFTY 50 spot</div><div class="v">${d.spot.toLocaleString('en-IN',{maximumFractionDigits:0})}</div><div class="d">${d.spot_age_min>45?'Market closed, last print ':'Live '}· ${ago(d.spot_time)}</div></div><div class="tile"><div class="eyebrow">India VIX</div><div class="v">${d.vix.toFixed(2)}</div><div class="d">Implies ±${d.sigma_pct}% (${Math.round(d.sigma_pts)} pts) over ${dte} days</div></div><div class="tile"><div class="eyebrow">Radar risk now</div><div class="v" style="color:${col}">${d.score}</div><div class="d">${d.band} · highest zone: ${esc(d.region_name||'-')}</div></div></div>
  <div class="card"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px"><div class="eyebrow">Short strikes: normal vs risk-adjusted</div><div class="seg" id="dsg">${[2,7,14,30].map(n=>`<button data-d="${n}" class="${n===dte?'on':''}">${n} days</button>`).join('')}</div></div>
  ${d.stand_aside?`<p class="lead" style="color:var(--avoid);margin-top:14px">Risk band is AVOID. The radar suggests standing aside from new short-premium positions. The strikes below are the widest the model would consider.</p>`:''}
  <svg viewBox="0 0 ${W} 170" style="width:100%;margin-top:14px">${tick(Math.round(d.spot),'#8b90a0','spot')}
   ${bar(40,B.short_put,B.short_call,'#8b90a0',`normal ${B.k}σ: ${B.short_put} to ${B.short_call}`,true)}
   ${bar(80,A.short_put,A.short_call,col,`risk-adjusted ${A.k}σ: ${A.short_put} to ${A.short_call}`,false)}
   <g id="gp" style="display:none"><line id="gl" x1="0" x2="0" y1="26" y2="150" stroke="#ff4d5e" stroke-width="2"/><text id="gt" y="165" fill="#ff4d5e" font-size="11" font-family="monospace" text-anchor="middle"></text></g></svg>
  <div class="legs"><div class="leg"><small>Buy call (wing)</small><b>${A.long_call}</b><i>caps loss above</i></div><div class="leg"><small>Sell call</small><b style="color:${col}">${A.short_call}</b><i>+${A.call_dist_pct}% from spot · ${d.widen_pts.call>=0?'+':''}${d.widen_pts.call} pts vs normal</i></div><div class="leg"><small>Sell put</small><b style="color:${col}">${A.short_put}</b><i>-${A.put_dist_pct}% from spot · ${d.widen_pts.put>=0?'+':''}${d.widen_pts.put} pts vs normal</i></div><div class="leg"><small>Buy put (wing)</small><b>${A.long_put}</b><i>caps loss below</i></div></div></div>
  <div class="grid2" style="margin-top:20px"><div class="card"><div class="eyebrow">Overnight gap test</div><p class="lead" style="margin:10px 0 14px">Drag to see where a gap would land against your strikes.</p><input type="range" id="gs" class="rng" min="-6" max="6" step="0.1" value="0" style="width:100%"><div id="gr" style="margin-top:12px;font-size:14px"></div></div>
  <div class="card"><div class="eyebrow">How it is computed</div><ul style="margin:10px 0 0 18px;color:var(--mute);line-height:1.8;font-size:13.5px"><li>Expected move = spot × VIX/100 × √(days/365). Both inputs are live quotes from Yahoo Finance.</li><li>Short strikes sit ${A.k}σ out for the ${d.band} band (${Object.entries(d.multiples).map(([k,x])=>k.toLowerCase()+' '+x+'σ').join(', ')}), rounded to 50, wings 100 pts wide.</li><li>The band comes from this radar's highest zone score. Multiples are a transparent rule, not a fitted model.</li><li>VIX is a forward-looking proxy and the geopolitical score is a proxy of feed activity. This is a planning aid, not advice or a forecast.</li></ul></div></div>`;
  $$('#dsg button').forEach(b=>b.onclick=()=>{dte=+b.dataset.d;draw()});
  $('#gs').oninput=e=>{const g=+e.target.value,p=d.spot*(1+g/100),px=x(p);$('#gp').style.display='';$('#gl').setAttribute('x1',px);$('#gl').setAttribute('x2',px);$('#gt').setAttribute('x',px);$('#gt').textContent=Math.round(p)+' ('+(g>0?'+':'')+g+'%)';
   const bc=p>A.short_call,bp=p<A.short_put,bb=p>B.short_call||p<B.short_put;$('#gr').innerHTML=`NIFTY at <b>${Math.round(p)}</b>: risk-adjusted strikes ${bc||bp?`<b style="color:var(--avoid)">breached (${bc?'call':'put'} side)</b>`:'<b style="color:var(--normal,#3ddc97)">hold</b>'}; normal strikes ${bb?'<b style="color:var(--avoid)">breached</b>':'<b style="color:var(--normal,#3ddc97)">hold</b>'}.`};$('#gs').oninput({target:$('#gs')});setUpd(new Date().toISOString())};
 draw()};
routes.method=async v=>{const s=await api('/api/settings');const W=s.weights,R=s.regions,sig=Object.keys(W);
 v.innerHTML=`<h1>Methodology</h1><p class="sub">How a score is built, with a simulator you can play with. The simulator only does arithmetic on the real weights; it does not read or change live data.</p>
 <div class="grid2"><div class="card"><div class="eyebrow">Score formula</div><p class="lead" style="margin:10px 0;max-width:none">Each active signal adds its weight. The sum is multiplied by the region factor and capped at 100. Crude and India VIX only count when at least one OSINT signal is active in the region, so one data family alone never raises a high alert. An alert needs two independent signal types.</p>
 <table><tr><th>Signal</th><th>Weight</th></tr>${sig.map(k=>`<tr><td>${SIG[k]}</td><td>${W[k]}</td></tr>`).join('')}</table>
 <table style="margin-top:14px"><tr><th>Region</th><th>Multiplier</th></tr>${Object.values(R).map(r=>`<tr><td>${esc(r.name)}</td><td>x${r.multiplier}</td></tr>`).join('')}</table></div>
 <div class="card"><div class="eyebrow">What-if simulator</div><div class="bar" style="margin-top:12px"><select id="sr">${Object.entries(R).map(([k,r])=>`<option value="${k}">${esc(r.name)}</option>`).join('')}</select></div>${sig.map(k=>`<label style="display:flex;gap:10px;padding:6px 0;cursor:pointer"><input type="checkbox" class="sg" value="${k}"> ${SIG[k]} <span style="color:var(--mute);margin-left:auto">+${W[k]}</span></label>`).join('')}
 <div class="stance" style="margin-top:14px;gap:18px"><div class="gauge" id="sg" style="width:120px;height:120px"></div><div><div class="big" id="sl" style="font-size:30px"></div><p class="lead" id="sa" style="font-size:13px"></p></div></div></div></div>
 <div class="card" style="margin-top:20px"><div class="eyebrow">Honest limits</div><ul style="margin:10px 0 0 18px;color:var(--mute);line-height:1.8;font-size:13.5px"><li>GPS degradation (NACp) is a proxy for interference, not confirmed jamming.</li><li>The military count is what the public ADS-B feed shows. A low count means few visible aircraft, not that none are present.</li><li>AIS comes from terrestrial receivers; a vessel going quiet can be a coverage edge.</li><li>GDELT counts are conflict-coded articles, which can include commentary and repeats.</li><li>Volatility and gap-risk indicator only. No direction call, no trade execution, no backtest.</li></ul></div>`;
 const calc=()=>{const on=[...document.querySelectorAll('.sg:checked')].map(x=>x.value),osint=on.filter(k=>!k.endsWith('_confirmation')),use=osint.length?on:[];const sc=Math.min(100,Math.round(use.reduce((a,k)=>a+W[k],0)*R[$('#sr').value].multiplier));
  const b=s.bands,l=sc>=b.avoid[0]?'AVOID':sc>=b.high[0]?'HIGH':sc>=b.caution[0]?'CAUTION':'NORMAL';$('#sg').innerHTML=ring(sc,l,120,8)+`<div class="n" style="font-size:34px"><div>${sc}</div></div>`;$('#sl').textContent=PLAY[l].t;$('#sl').style.color=colr(l);$('#sa').textContent=on.length&&!osint.length?'Market confirmation alone scores 0: it needs at least one OSINT signal.':PLAY[l].a};
 document.querySelectorAll('.sg,#sr').forEach(x=>x.onchange=calc);calc()};
routes.briefing=async v=>{const [o,...rs]=await Promise.all([api('/api/overview'),...Object.keys(RN).slice(0,3).map(r=>api('/api/region/'+r+'?hours=24'))]);const lab=o.overall;
 v.innerHTML=`<div class="bar" style="justify-content:space-between"><div><h1>Daily briefing</h1><p class="sub" style="margin:0">${new Date().toLocaleDateString([], {weekday:'long',day:'numeric',month:'long',year:'numeric'})} · generated from live data at ${new Date().toLocaleTimeString()}</p></div><button class="btn" onclick="window.print()">Save as PDF</button></div>
 <div class="card"><div class="eyebrow">Overall stance</div><div class="big" style="color:${colr(lab)}">${PLAY[lab].t} · ${o.max_score}/100</div><p class="lead">${PLAY[lab].a}</p>${PLAY[lab].d.map(x=>`<div class="step"><i>-</i><div>${x}</div></div>`).join('')}</div>
 <div class="grid3" style="margin-top:20px">${rs.map(r=>`<div class="card"><div class="eyebrow">${esc(r.name)}</div><div class="sc" style="font:600 46px var(--serif);color:${colr(r.current?r.current.label:'NORMAL')}">${r.current?r.current.score:0}</div>${badge(r.current?r.current.label:'NORMAL')}<p style="margin-top:12px;font-size:13px;color:var(--mute)">${r.current&&r.current.active_signals.length?r.current.active_signals.map(a=>esc(a.evidence)).join('<br>'):'No active signals.'}</p></div>`).join('')}</div>
 <div class="grid2"><div class="card"><div class="eyebrow">Market</div><div class="market" style="margin-top:12px">${tile('Brent crude',o.market.brent)}${tile('India VIX',o.market.india_vix)}</div></div><div class="card"><div class="eyebrow">Alerts in the last stored window</div><div class="tl">${o.alerts.length?o.alerts.slice(0,5).map(alertRow).join(''):'<div class="empty">None. No region had two independent signal types.</div>'}</div></div></div>
 <p class="lead" style="font-size:12px;max-width:none;margin-top:14px">Volatility and gap-risk indicator for NIFTY option sellers. It does not predict direction. GPS degradation is a proxy for interference, not confirmed jamming; counts reflect what public feeds show.</p>`;setUpd(o.now)};
function setUpd(t){$('#live').className='dot';$('#upd').textContent='updated '+ago(t||Date.now())}
// ---------- boot
document.querySelectorAll('.sw button').forEach(b=>b.onclick=()=>{localStorage.theme=b.dataset.t;document.documentElement.dataset.theme=b.dataset.t;route()});
if(new URLSearchParams(location.search).get('static')==='1')document.documentElement.classList.add('noanim');const th=new URLSearchParams(location.search).get('theme')||localStorage.theme||'obsidian';document.documentElement.dataset.theme=th;
fetch('/auth/me').then(r=>r.json()).then(m=>{if(m.auth_required&&!m.authenticated)showLogin();else route()});
setInterval(()=>{const h=location.hash;if(['','#/','#/briefing','#/feeds'].includes(h))route()},60000);

/* count-up on numeric stats; honours reduced motion and ?static=1 */
(function(){const off=matchMedia('(prefers-reduced-motion: reduce)').matches||document.documentElement.classList.contains('noanim');if(off)return;
const fmt=(t,n,dec)=>t.replace(/[\d,]+(\.\d+)?/,n.toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec}));
function run(el){if(el.dataset.cu)return;const t=el.textContent.trim();const m=t.match(/^([^\d-]*)([\d,]+(\.\d+)?)(.{0,3})$/);if(!m)return;el.dataset.cu=1;const end=parseFloat(m[2].replace(/,/g,'')),dec=(m[3]||'.').length-1,pre=m[1],suf=m[4];if(!isFinite(end)||end===0)return;const t0=performance.now(),D=900;
function f(now){const k=Math.min(1,(now-t0)/D),e=1-Math.pow(1-k,4),v=end*e;el.textContent=pre+v.toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec})+suf;if(k<1)requestAnimationFrame(f);else el.textContent=t}requestAnimationFrame(f)}
const scan=()=>document.querySelectorAll('#view .v,#view .sc,#view .big,#view .num,#view .tile .v').forEach(run);
new MutationObserver(()=>{requestAnimationFrame(()=>{scan();document.querySelectorAll('#view svg.chart>path[fill=none],#view svg path[fill=none][stroke-width]').forEach(p=>{if(!p.hasAttribute('pathLength')&&p.closest('svg:not([data-nodraw])')&&!p.closest('.leaflet-container'))p.setAttribute('pathLength','1')})})}).observe(document.getElementById('view'),{childList:true,subtree:false});scan()})();
